import {
  FileIcon,
  FileMediaIcon,
  ImageIcon,
  TrashIcon,
  UnmuteIcon,
  UploadIcon,
  VideoIcon,
  XIcon,
} from '@primer/octicons-react'
import {ActionList, ConfirmationDialog, Dialog, IconButton} from '@primer/react'
import {useCallback, useEffect, useRef, useState} from 'react'

import {useFilesContext} from '../../../contexts/FilesContext'
import {useFileSyncerContext} from '../../../contexts/FileSyncerContext'
import {useFetchFromCodespaceApi} from '../../../hooks/use-fetch-from-codespace-api'
import {ReadOnlyKey, useReadOnly} from '../../../hooks/use-read-only'
import {useWorkbenchNavigate} from '../../../hooks/use-workbench-navigate'
import {useIterateAnalytics} from '../../../telemetry/use-analytics'
import {
  type Asset,
  cleanupAssetBlobUrl,
  cleanupBlobUrl,
  createAssetContentUrl,
  deleteAssetFromAgent,
  downloadAssetFromAgent,
  downloadAssetToComputer,
  getAssetInfo,
  getAssetsList,
  getReadableFileSize,
  getSupportedAssetExtensions,
  shouldRefreshAssets,
  uploadAssetToAgent,
  validateFilesForUpload,
} from '../../../utilities/asset-utils'
import {EditorLoadingSkeleton} from '../../EditorLoadingSkeleton'
import {MediaPreview} from '../../MediaPreview/MediaPreview'
import {Section} from '../Section'
import styles from './AssetsPanel.module.css'

const ASSET_ICONS = {
  image: ImageIcon,
  video: VideoIcon,
  audio: UnmuteIcon,
  document: FileIcon,
  default: FileMediaIcon,
}

function getAssetIcon(asset: Asset) {
  const IconComponent = ASSET_ICONS[asset.category] || ASSET_ICONS.default
  return <IconComponent />
}

const CONSTANTS = {
  INCLUDE_MEDIA: true, // Always include media files
  MAX_FILE_SIZE: 25 * 1024 * 1024, // 25MB
} as const

// Error types for asset uploads
interface AssetUploadError {
  type: 'frontend_size_limit' | 'backend_size_limit' | 'storage_limit_exceeded'
  message: string
  fileName?: string
  fileSize?: number
  fileLimit?: number
  totalLimit?: number
  totalCurrent?: number
}

export function AssetsPanel() {
  const {getFileList} = useFilesContext()
  const {getFileSyncerV2, syncerMode} = useFileSyncerContext()
  const {fetchFromCodespaceApi} = useFetchFromCodespaceApi()
  const {iterateStarted, iterateSuccess} = useIterateAnalytics('assets_panel')
  const workbenchNavigate = useWorkbenchNavigate()

  // State management
  const [assets, setAssets] = useState<Asset[]>([])
  const [openAsset, setOpenAsset] = useState<Asset>()
  const [loadingAssetContent, setLoadingAssetContent] = useState<boolean>(false)
  const [hoveredAsset, setHoveredAsset] = useState<string | null>(null)
  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState<boolean>(false)
  const [assetToDelete, setAssetToDelete] = useState<Asset | null>(null)
  const [isUploading, setIsUploading] = useState<boolean>(false)
  const [isManualRefresh, setIsManualRefresh] = useState<boolean>(false)
  const [uploadError, setUploadError] = useState<AssetUploadError | null>(null)

  // Refs
  const fileInputRef = useRef<HTMLInputElement>(null)
  const blobUrlsRef = useRef<Set<string>>(new Set())

  // Computed values
  const fileSyncerConnected = syncerMode === 'codespace'
  const readOnly = useReadOnly(ReadOnlyKey.ASSETS_PANEL)
  const isUploadDisabled = readOnly || !fileSyncerConnected || isUploading

  // Get list of all assets with their sizes
  const refreshAssets = useCallback(
    async (isManual = false) => {
      if (isManual) {
        setIsManualRefresh(true)
      }

      try {
        const newAssets = await getAssetsList(fetchFromCodespaceApi)
        setAssets(newAssets)
      } catch {
        // Handle error silently - getAssetsList already handles errors
      }

      if (isManual) {
        setIsManualRefresh(false)
      }
    },
    [fetchFromCodespaceApi],
  )

  useEffect(() => {
    // Only refresh automatically if it's not a manual refresh
    if (!isManualRefresh) {
      const fileList = getFileList()

      // Use utility function to check if assets need to be refreshed
      if (shouldRefreshAssets(fileList, assets)) {
        refreshAssets()
      }
    }
  }, [getFileList, refreshAssets, isManualRefresh, assets])

  // Load asset content when dialog is opened
  const loadAssetContent = useCallback(
    async (asset: Asset): Promise<void> => {
      if (asset.content) return // Already loaded

      setLoadingAssetContent(true)
      try {
        const blob = await downloadAssetFromAgent(asset.path, fetchFromCodespaceApi)

        if (blob) {
          const content = await createAssetContentUrl(blob, asset.name, CONSTANTS.INCLUDE_MEDIA, blobUrlsRef.current)
          const size = getReadableFileSize(blob.size)

          const updatedAsset: Asset = {
            ...asset,
            content,
            size: blob.size,
            sizePretty: size,
          }

          setAssets(prev => prev.map(a => (a.name === asset.name ? updatedAsset : a)))
          setOpenAsset(updatedAsset)
        }
      } catch {
        // Handle error silently
      } finally {
        setLoadingAssetContent(false)
      }
    },
    [fetchFromCodespaceApi],
  )

  // Upload a single file to the agent server
  const processFileUpload = useCallback(
    async (file: File): Promise<void> => {
      try {
        await uploadAssetToAgent(file, file.name, fetchFromCodespaceApi)
      } catch (error) {
        // Parse API error and re-throw with file context
        if (error instanceof Error) {
          const apiError = error as Error & {
            code?: string
            data?: {
              fileSize?: number
              fileLimit?: number
              totalLimit?: number
              totalCurrent?: number
            }
          }

          // Create enhanced error with file information
          const enhancedError = new Error(error.message) as Error & {
            code?: string
            fileName: string
            fileSize: number
            data?: typeof apiError.data
          }

          enhancedError.code = apiError.code
          enhancedError.fileName = file.name
          enhancedError.fileSize = file.size
          enhancedError.data = apiError.data

          throw enhancedError
        }
        throw error
      }
    },
    [fetchFromCodespaceApi],
  )

  // Upload multiple files and refresh asset list
  const uploadFiles = useCallback(
    async (files: File[]): Promise<void> => {
      setIsUploading(true)
      setIsManualRefresh(true) // Prevent automatic refresh during upload

      try {
        // Process all files concurrently
        await Promise.all(files.map(processFileUpload))

        // Manually refresh assets after upload
        const newAssets = await getAssetsList(fetchFromCodespaceApi)
        setAssets(newAssets)
      } catch (error) {
        // Handle specific error cases
        if (error instanceof Error) {
          const apiError = error as Error & {
            code?: string
            fileName?: string
            fileSize?: number
            data?: {
              fileSize?: number
              fileLimit?: number
              totalLimit?: number
              totalCurrent?: number
            }
          }

          if (apiError.code === 'FILE_TOO_LARGE') {
            const fileLimitMB = apiError.data?.fileLimit ? Math.round(apiError.data.fileLimit / (1024 * 1024)) : 10
            const fileSizeFormatted = apiError.fileSize ? getReadableFileSize(apiError.fileSize) : 'Unknown size'
            setUploadError({
              type: 'backend_size_limit',
              message: `File "${apiError.fileName}" (${fileSizeFormatted}) exceeds the ${fileLimitMB}MB size limit.`,
              fileName: apiError.fileName,
              fileSize: apiError.fileSize,
              fileLimit: fileLimitMB,
            })
          } else if (apiError.code === 'TOTAL_SIZE_LIMIT_EXCEEDED') {
            const totalLimitMB = apiError.data?.totalLimit ? Math.round(apiError.data.totalLimit / (1024 * 1024)) : 100
            const totalCurrentMB = apiError.data?.totalCurrent
              ? Math.round(apiError.data.totalCurrent / (1024 * 1024))
              : 0
            const fileSizeFormatted = apiError.fileSize ? getReadableFileSize(apiError.fileSize) : 'Unknown size'
            setUploadError({
              type: 'storage_limit_exceeded',
              message: `File "${apiError.fileName}" (${fileSizeFormatted}) would exceed the ${totalLimitMB}MB storage limit. Current usage: ${totalCurrentMB}MB.`,
              fileName: apiError.fileName,
              fileSize: apiError.fileSize,
              totalLimit: totalLimitMB,
              totalCurrent: totalCurrentMB,
            })
          }
        }
      } finally {
        setIsUploading(false)
        setIsManualRefresh(false) // Re-enable automatic refresh
      }
    },
    [processFileUpload, fetchFromCodespaceApi],
  )

  // Handle file input changes
  const handleFileUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files
      if (!files || files.length === 0) return

      const telemetryProperties = iterateStarted()
      const selectedFiles = Array.from(files)

      // Validate file sizes
      const {validFiles, invalidFiles} = validateFilesForUpload(selectedFiles, CONSTANTS.MAX_FILE_SIZE)

      // Validate file sizes and show error dialog for oversized files
      if (invalidFiles.length > 0) {
        const firstInvalidFile = selectedFiles.find(file => file.size > CONSTANTS.MAX_FILE_SIZE)
        if (firstInvalidFile) {
          const fileSizeLimit = CONSTANTS.MAX_FILE_SIZE / (1024 * 1024)
          const errorMessage =
            invalidFiles.length === 1
              ? `File "${firstInvalidFile.name}" (${getReadableFileSize(
                  firstInvalidFile.size,
                )}) exceeds the ${fileSizeLimit}MB size limit.`
              : `${invalidFiles.length} files exceed the ${fileSizeLimit}MB size limit. First file: "${
                  firstInvalidFile.name
                }" (${getReadableFileSize(firstInvalidFile.size)})`

          setUploadError({
            type: 'frontend_size_limit',
            message: errorMessage,
            fileName: firstInvalidFile.name,
            fileSize: firstInvalidFile.size,
            fileLimit: fileSizeLimit,
          })
        }
        return // Don't proceed with upload
      }

      // Upload valid files
      if (validFiles.length > 0) {
        try {
          await uploadFiles(validFiles)
          iterateSuccess(telemetryProperties)
        } catch {
          // Error is handled in uploadFiles via setUploadError
        }
      }

      // Clear input for re-upload
      e.target.value = ''
    },
    [iterateStarted, iterateSuccess, uploadFiles],
  )

  // Trigger file input dialog
  const triggerFileInput = useCallback(() => {
    if (!isUploadDisabled) {
      fileInputRef.current?.click()
    }
  }, [isUploadDisabled])

  // Open delete confirmation dialog
  const openDeleteAssetDialog = useCallback((asset: Asset) => {
    setAssetToDelete(asset)
    setIsDeleteConfirmationOpen(true)
  }, [])

  // Delete an asset from both backend and file system
  const deleteAsset = useCallback(
    async (asset: Asset) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer) return

      try {
        // Delete from backend and file system
        await Promise.all([deleteAssetFromAgent(asset.path, fetchFromCodespaceApi), fileSyncer.deleteFile(asset.path)])

        // Clean up any blob URLs
        cleanupAssetBlobUrl(asset, blobUrlsRef.current)

        // Close dialog if deleted asset is open
        if (openAsset?.name === asset.name) {
          setOpenAsset(undefined)
        }

        // Check if we're currently viewing the asset being deleted and navigate away
        const shouldNavigateAway = (() => {
          const currentPath = window.location.pathname

          // Extract relative path from /file/ onwards from the current path
          const filePathMatch = currentPath.match(/\/file\/(.+)$/)
          if (!filePathMatch) {
            return false
          }

          const currentFilePath = filePathMatch[1]

          // Get the asset path relative to the workspace (extract from src/ onwards)
          const assetPath = asset.path.includes('/src/')
            ? asset.path.substring(asset.path.indexOf('/src/') + 1) // Extract "src/..." part
            : asset.path.startsWith('/')
              ? asset.path.substring(1)
              : asset.path

          // Check both URL-encoded and unencoded versions
          const encodedAssetPath = encodeURI(assetPath)
          return currentFilePath === assetPath || currentFilePath === encodedAssetPath
        })()

        if (shouldNavigateAway) {
          workbenchNavigate('src/App.tsx')
        }

        // Refresh asset list
        await refreshAssets(true)
      } catch {
        // Handle error silently
      }
    },
    [getFileSyncerV2, fetchFromCodespaceApi, openAsset, refreshAssets, workbenchNavigate],
  )

  // Download an asset to computer
  const downloadAsset = useCallback((asset: Asset) => {
    downloadAssetToComputer(asset)
  }, [])

  // Cleanup blob URLs when component unmounts
  useEffect(() => {
    const urlsSet = blobUrlsRef.current
    return () => {
      // Clean up all blob URLs
      cleanupBlobUrl(Array.from(urlsSet))
    }
  }, [])

  return (
    <div className="tmp-mt-3">
      <Section title="Assets" showTitle={false} readOnly={isUploadDisabled} loading={isUploading}>
        <Section.PrimaryAction icon={UploadIcon} onSelect={triggerFileInput}>
          {isUploading ? 'Uploading...' : 'Upload files'}
        </Section.PrimaryAction>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileUpload}
          className="d-none"
          accept={getSupportedAssetExtensions(CONSTANTS.INCLUDE_MEDIA).join(',')}
          multiple
        />

        <Section.Items>
          <p className="fgColor-muted text-small mt-1 mb-0">
            Upload assets here or in the Iterate panel. Assets support images, documents, audio, and video. Ask in the
            Iterate panel to add them to your app.
          </p>
        </Section.Items>

        {assets.length > 0 && (
          <ActionList>
            {assets.map(asset => (
              <ActionList.Item
                key={asset.name}
                className={styles.listItem}
                onSelect={() => {
                  // Show dialog immediately
                  setOpenAsset(asset)
                  // Start loading content in the background if not already loaded
                  if (!asset.content) {
                    loadAssetContent(asset)
                  }
                }}
                onMouseEnter={() => setHoveredAsset(asset.name)}
                onMouseLeave={() => setHoveredAsset(null)}
              >
                <ActionList.LeadingVisual>{getAssetIcon(asset)}</ActionList.LeadingVisual>
                {asset.name}
                <ActionList.Description variant="block">{getAssetInfo(asset)}</ActionList.Description>
                {hoveredAsset === asset.name && (
                  <ActionList.TrailingAction
                    label={`Delete ${asset.name}`}
                    icon={TrashIcon}
                    onMouseEnter={() => setHoveredAsset(asset.name)}
                    onMouseLeave={() => setHoveredAsset(null)}
                    onClick={(e: React.MouseEvent) => {
                      e.stopPropagation() // Prevent opening the dialog
                      openDeleteAssetDialog(asset)
                    }}
                  />
                )}
              </ActionList.Item>
            ))}
          </ActionList>
        )}
      </Section>

      {openAsset && (
        <Dialog
          onClose={() => {
            setOpenAsset(undefined)
          }}
          renderHeader={() => {
            // Find the most up-to-date asset info from the assets array
            const currentAsset = assets.find(a => a.name === openAsset.name) || openAsset
            // Also use openAsset if it has more recent updates
            const mostCurrentAsset = openAsset.content && !currentAsset.content ? openAsset : currentAsset
            return (
              <div className="tmp-p-3 border-bottom">
                <div className="d-flex flex-justify-between flex-items-center">
                  <span className={styles.dialogTitle}>{mostCurrentAsset.name}</span>
                  <IconButton
                    aria-label="Close asset dialog"
                    size="small"
                    variant="invisible"
                    icon={XIcon}
                    onClick={() => {
                      setOpenAsset(undefined)
                    }}
                  />
                </div>

                <span className={styles.dialogSubtitle}>{getAssetInfo(mostCurrentAsset)}</span>
              </div>
            )
          }}
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Download',
              onClick: () => downloadAsset(openAsset),
            },
            {
              buttonType: 'danger',
              content: 'Delete',
              onClick: () => {
                setOpenAsset(undefined)
                openDeleteAssetDialog(openAsset)
              },
            },
          ]}
        >
          {!openAsset.content || loadingAssetContent ? (
            <EditorLoadingSkeleton fadeIn />
          ) : (
            <MediaPreview src={openAsset.content} filePath={openAsset.path} alt={`${openAsset.name} preview`} />
          )}
        </Dialog>
      )}

      {isDeleteConfirmationOpen && assetToDelete && (
        <ConfirmationDialog
          title="Delete asset"
          onClose={gesture => {
            if (gesture === 'confirm') {
              deleteAsset(assetToDelete)
            }
            setIsDeleteConfirmationOpen(false)
            setAssetToDelete(null)
          }}
          confirmButtonContent="Delete"
          confirmButtonType="danger"
        >
          Are you sure you want to delete {assetToDelete.name}?
        </ConfirmationDialog>
      )}

      {uploadError && (
        <ConfirmationDialog
          title={uploadError.type === 'storage_limit_exceeded' ? 'Storage limit exceeded' : 'Asset too large'}
          onClose={() => setUploadError(null)}
          confirmButtonContent="OK"
          confirmButtonType="primary"
        >
          {uploadError.type === 'frontend_size_limit' &&
            (() => {
              const fileSize = uploadError.fileSize ? getReadableFileSize(uploadError.fileSize) : 'Unknown size'
              const limit = uploadError.fileLimit ? getReadableFileSize(uploadError.fileLimit * 1024 * 1024) : '10 MB'
              return (
                <span>
                  File is too large ({fileSize}), the limit is {limit}.
                </span>
              )
            })()}
          {uploadError.type === 'backend_size_limit' &&
            (() => {
              const fileSize = uploadError.fileSize ? getReadableFileSize(uploadError.fileSize) : 'Unknown size'
              const limit = uploadError.fileLimit ? getReadableFileSize(uploadError.fileLimit * 1024 * 1024) : '10 MB'
              return (
                <span>
                  File is too large ({fileSize}), the limit is {limit}.
                </span>
              )
            })()}
          {uploadError.type === 'storage_limit_exceeded' &&
            (() => {
              const totalLimit = uploadError.totalLimit || 100
              const totalCurrent = uploadError.totalCurrent || 0
              const availableMB = totalLimit - totalCurrent
              const available = getReadableFileSize(availableMB * 1024 * 1024)
              return <span>Not enough storage, {available} available.</span>
            })()}
        </ConfirmationDialog>
      )}
    </div>
  )
}
